CREATE VIEW "EXT"."CSA_PROD_AGENTES_SVW_O" ( "REGIONAL", "SUCURSAL", "OFICINA", "COD_AGENTE", "AGENTE", "POSITIONNAME", "NIF", "NIF_NOMBRE", "CUADRO", "TIPO_AGENTE", "AGENTES_ACTIVOS", "MANAGER", "MANAGER_NOMBRE", "MANAGER_NIF", "PRODUCTOS", "ASEG", "POL_FIS", "POL_CORR", "PRIMAS", "ID_TIPO_AGENTE", "YEAR", "PERIODO", "PERIODO_FORMATO", "PERIODO_TABLA", "IGUALES", "FEC_ACTUALIZACION", "POSITIONSEQ", "PERIODSEQ" ) AS (SELECT "REGIONAL" , "SUCURSAL" , "OFICINA" , "COD_AGENTE" , "AGENTE" , "POSITIONNAME" , "NIF" , "NIF_NOMBRE" , "CUADRO" , "TIPO_AGENTE" , "AGENTES_ACTIVOS" , "MANAGER" , "MANAGER_NOMBRE" , "MANAGER_NIF" , "PRODUCTOS" , "ASEG" , "POL_FIS" , "POL_CORR" , "PRIMAS" , ID_TIPO_AGENTE, "YEAR" , "PERIODO" , "PERIODO_FORMATO" , "PERIODO_TABLA", "IGUALES" , "FEC_ACTUALIZACION" , "POSITIONSEQ" , "PERIODSEQ" 
    FROM EXT.OUT_PROD_AGENTES_FINAL_REP
    WHERE PERIODSEQ IN (SELECT PERIODSEQ FROM EXT.LIB_CREAR_TABLAS:N_MESES(13))) WITH  STRUCTURED PRIVILEGE CHECK